from pathlib import Path
paths = [Path('README.md'), *Path('docs/02-how-to/extraction').glob('*.md'), *Path('docs/03-reference/systems/repo-truth-extractor').glob('*.md'), *Path('docs/03-reference/truth').glob('*.md')]
checks = {'dopemux upgrades': ('legacy','compatibility','do not use','not use','stale command'), 'dopemux extractor': ('legacy','deprecated','hidden','blocked','refusal','deprioritized'), 'dopemux truth': ('legacy','refusal','not the v5','deprioritized'), 'dopemux extract truth-run': ('legacy','compatibility','hidden','disabled','refusal'), 'PipelineRunner': ('legacy','not the v5','drift'), 'python services/repo-truth-extractor/run_extraction_v5.py': ('advanced','debug','manual','runner-level','specific runbook'), 'run_repscan': ('legacy','gated')}
failures=[]
for path in sorted(paths):
    if not path.exists():
        continue
    lines = path.read_text(encoding='utf-8').splitlines(); whole='\n'.join(lines).lower()
    for i,line in enumerate(lines,1):
        low=line.lower()
        for term,allowed in checks.items():
            if term.lower() not in low:
                continue
            window='\n'.join(lines[max(0,i-6):min(len(lines),i+6)]).lower()
            if not any(marker in window for marker in allowed) and not any(marker in whole for marker in allowed):
                failures.append(f'{path}:{i}: {term} lacks classification context: {line}')
if failures:
    print('\n'.join(failures)); raise SystemExit(1)
print('legacy-classification-ok')
